/**
 * Overlapping matches from different layers must be unioned, never dropped:
 * a match that starts inside an earlier one can reach further, and dropping
 * it left the tail of a secret visible. Synthetic values only, assembled at
 * runtime so no token-shaped literal sits in the source.
 */

import { describe, test, expect } from "vitest";
import { buildTable, mask, DEFAULT_PATTERNS } from "../src/mask.js";

const KEY = "AK" + "IA";
const BULLET = "•";

describe("overlapping matches are unioned", () => {
  test("an entropy piece next to a prefix token masks both, including a second prefix hit", () => {
    const table = buildTable([], {}, DEFAULT_PATTERNS, { entropy: true });
    const second = `${KEY}J7QWERTYEXAMPLE9`;
    const input = `k=Zx8Qp2Lm9Vt4Rb7Nk3Wy6Hc${KEY}Q=${second} end`;
    const out = mask(input, table).text;
    expect(out).not.toContain(second);
    expect(out).not.toContain("Zx8Qp2");
    expect(out.startsWith("k=")).toBe(true);
    expect(out.endsWith(" end")).toBe(true);
  });

  test("a named value ending inside a prefix token does not hide the rest of the token", () => {
    const named = `zzzzzz${KEY}x`;
    const tail = `${KEY}SECRETSECRET`;
    const table = buildTable(["X_NAMED"], { X_NAMED: named }, DEFAULT_PATTERNS, { entropy: true });
    const out = mask(`before ${named}${tail} after`, table).text;
    expect(out).not.toContain(tail);
    expect(out).not.toContain("SECRETSECRET");
    expect(out).not.toContain("zzzzzz");
  });

  test("two overlapping named values are both fully covered", () => {
    const x = "QQQQQQQa";
    const y = "abababab";
    const table = buildTable(["X_A", "Y_B"], { X_A: x, Y_B: y }, DEFAULT_PATTERNS, { entropy: true });
    // X ends with "a", which is where Y begins: the two copies overlap by one character.
    const out = mask(`v ${"QQQQQQQ"}abababab w`, table).text;
    expect(out).not.toContain("QQQQ");
    expect(out).not.toContain("bab");
    expect(out).toContain(BULLET);
  });

  test("a self-overlapping named value leaves no fragment visible", () => {
    const table = buildTable(["Z_C"], { Z_C: "abababab" }, DEFAULT_PATTERNS, { entropy: false });
    const out = mask("x ababababab y", table).text;
    expect(out).toBe(`x ${BULLET.repeat(8)} y`);
  });
});
